class TodoList:
    def __init__(self):
        self.tasks = []

    def add(self, task):
        self.tasks.append(task)

    def done(self, task):
        if task in self.tasks:
            self.tasks.remove(task)
            return True
        return False

    def pending(self):
        return list(self.tasks)

    def count(self):
        return len(self.tasks)

